  async function adminOverview(content) {
    const data=await api('/api/admin/dashboard'); const m=data.metrics;
    const enquiryLabels={new:'New',contacted:'Contacted',trial_booked:'Trial booked',closed:'Closed'};
    const enquiryTotal=Math.max(1,Object.values(data.enquiry_mix).reduce((sum,value)=>sum+Number(value),0));
    const enquiries=Object.entries(data.enquiry_mix).map(([key,value])=>`<div class="ops-bar-row"><div class="ops-bar-label"><strong>${esc(enquiryLabels[key]||key)}</strong><span>${value} · ${Math.round(100*value/enquiryTotal)}%</span></div><div class="ops-bar-track" aria-label="${esc(enquiryLabels[key]||key)}: ${value}"><span class="ops-bar-fill enquiry-${esc(key)}" style="width:${value?Math.max(4,100*value/enquiryTotal):0}%"></span></div></div>`).join('');
    const classes=data.classes.map(item=>`<div class="ops-bar-row"><div class="ops-bar-label"><strong>${esc(item.title)}</strong><span>${item.enrolled}/${item.capacity} · ${item.utilisation}%</span></div><div class="ops-bar-track" aria-label="${esc(item.title)} utilisation ${item.utilisation}%"><span class="ops-bar-fill" style="width:${Math.min(100,item.utilisation)}%"></span></div><small>${esc(item.code)} · ${esc(item.location_name)} · ${item.available} places available</small></div>`).join('');
    const hourLabels={draft:'Draft',submitted:'Awaiting approval',approved:'Approved',exported:'Sent to Xero'};
    const hourTotal=Object.values(data.hour_mix).reduce((sum,value)=>sum+Number(value),0);
    const hours=Object.entries(data.hour_mix).map(([key,value])=>`<div class="hours-key"><span class="hours-dot hours-${esc(key)}"></span><strong>${esc(hourLabels[key]||key)}</strong><em>${Number(value).toFixed(1)} h</em></div>`).join('');
    const hourStack=hourTotal?Object.entries(data.hour_mix).map(([key,value])=>`<span class="hours-segment hours-${esc(key)}" style="width:${100*value/hourTotal}%" title="${esc(hourLabels[key]||key)}: ${Number(value).toFixed(1)} hours"></span>`).join(''):'<span class="hours-segment hours-empty" style="width:100%"></span>';
    const pools=data.locations.map(item=>{const reading=item.latest_reading;const complete=item.latest_checklist&&['deck_safe','first_aid_ready','equipment_ready','water_checked'].every(key=>item.latest_checklist[key]);return `<article class="readiness-card"><div class="readiness-top"><div><span>${esc(item.venue_type)}</span><h3>${esc(item.name)}</h3></div>${chip(item.public_status,statusKind(reading?.status||'demo'))}</div><div class="readiness-reading"><strong>${reading?.temperature!=null?`${Number(reading.temperature).toFixed(1)}°C`:'Check due'}</strong><span>${reading?`Last verified ${dt(reading.created_at)}`:'No water reading published'}</span></div><div class="readiness-flags"><span class="${item.reading_fresh?'ready':'due'}">${item.reading_fresh?'✓':'!'} Water reading</span><span class="${item.checklist_fresh&&complete?'ready':'due'}">${item.checklist_fresh&&complete?'✓':'!'} Opening check</span><span>${item.today_classes} classes today</span></div><button class="btn btn-soft btn-small" data-route-jump="locations">Manage venue</button></article>`}).join('');
    const definitions=Object.entries(data.definitions).map(([key,value])=>`<div><strong>${esc(key.replaceAll('_',' '))}</strong><span>${esc(value)}</span></div>`).join('');
    content.innerHTML=shell('HV Swim command centre','A clear operating picture across enrolments, classes, staff hours and pool readiness.',`<div class="ops-source"><div><span class="live-dot"></span><strong>${esc(data.source.name)}</strong><small>${esc(data.source.mode)} · refreshed ${dt(data.generated_at)}</small></div><div class="export-actions"><a href="/api/admin/exports/enquiries.csv">Enquiries CSV</a><a href="/api/admin/exports/timesheets.csv">Timesheets CSV</a><a href="/api/admin/exports/products.csv">Merch CSV</a></div></div><div class="platform-grid">${metric('Active swimmers',m.active_swimmers,'Active swimmer profiles','♡')}${metric('Confirmed bookings',m.confirmed_bookings,`${m.waitlist} currently waitlisted`,'▦')}${metric('New enquiries',m.new_enquiries,`${m.enquiries_total} enquiries in workflow`,'✉')}${metric('Class utilisation',`${m.class_utilisation}%`,`${m.confirmed_bookings} of ${m.class_capacity} places`,'↗')}<section class="panel panel-pad p-span-5"><div class="panel-head"><div><h2>Enquiry workload</h2><p>Current records by status—not a conversion funnel</p></div><button class="btn btn-soft btn-small" data-route-jump="enquiries">Open inbox</button></div><div class="ops-bar-chart">${enquiries}</div></section><section class="panel panel-pad p-span-7"><div class="panel-head"><div><h2>Class capacity</h2><p>Confirmed bookings against each active class limit</p></div><button class="btn btn-soft btn-small" data-route-jump="classes">Manage classes</button></div><div class="ops-bar-chart class-bars">${classes||empty('No active classes are available.')}</div></section><section class="panel panel-pad p-span-5"><div class="panel-head"><div><h2>Staff hours pipeline</h2><p>${hourTotal.toFixed(1)} hours recorded across all workflow stages</p></div><button class="btn btn-soft btn-small" data-route-jump="timesheets">Review</button></div><div class="hours-stack" aria-label="Staff hours by workflow status">${hourStack}</div><div class="hours-legend">${hours}</div><div class="priority-callout"><span>Needs approval</span><strong>${Number(m.pending_hours).toFixed(1)} h</strong></div></section><section class="panel panel-pad p-span-7"><div class="panel-head"><div><h2>Pool readiness</h2><p>${m.pool_readings_current} of ${m.pool_locations} locations have a water reading from the last 24 hours</p></div><button class="btn btn-soft btn-small" data-route-jump="locations">All locations</button></div><div class="pool-readiness-grid">${pools}</div></section><section class="panel panel-pad p-span-12"><div class="panel-head"><div><h2>Metric definitions & data boundary</h2><p>Definitions travel with the dashboard so numbers remain accountable.</p></div>${chip('Preview data','changed')}</div><div class="definition-grid">${definitions}</div><div class="data-boundary"><strong>Production boundary:</strong> These figures come from this Mac's local SQLite preview database. They become live business metrics after authorised customer, class and staff data is migrated to the production database. No fabricated historical trend is shown.</div></section></div>`);
  }

  async function adminEnrolments(content) {
    const data=await api('/api/admin/enrolments'); const s=data.summary;
    const today=data.classes.filter(item=>item.is_today);
    const todayRows=today.map(item=>`<article class="run-sheet-row"><div class="run-time"><strong>${esc(item.start_time)}</strong><span>${item.duration_minutes} min</span></div><div class="run-main"><span>${esc(item.code)} · ${esc(item.location_name)}</span><h3>${esc(item.title)}</h3><p>${esc(item.instructor_first||'Instructor TBC')} ${esc(item.instructor_last||'')} · ${item.enrolled}/${item.capacity} confirmed</p></div><div class="run-capacity"><strong>${item.available}</strong><span>places left</span></div></article>`).join('');
    const weekly=data.classes.map(item=>`<article class="schedule-card ${item.is_today?'today':''}"><div class="schedule-card-top"><span>${esc(weekday[item.weekday])}</span>${item.is_today?chip('Today','open'):chip(`${item.available} open`,item.available?'demo':'changed')}</div><strong>${esc(item.start_time)}</strong><h3>${esc(item.title)}</h3><p>${esc(item.location_name)}<br>${esc(item.instructor_first||'Instructor TBC')} ${esc(item.instructor_last||'')}</p><div class="capacity-meter"><span style="width:${Math.min(100,item.utilisation)}%"></span></div><small>${item.enrolled}/${item.capacity} confirmed · ${item.waiting} waiting</small></article>`).join('');
    const queue=data.waitlist.map(entry=>`<article class="waitlist-desk-row"><div class="waitlist-position">${entry.position}</div><div class="waitlist-person"><span>${esc(entry.code)} · ${esc(weekday[entry.weekday])} ${esc(entry.start_time)}</span><h3>${esc(entry.swimmer_first)} ${esc(entry.swimmer_last)}</h3><p>Family: ${esc(entry.customer_first)} ${esc(entry.customer_last)} · <a href="mailto:${esc(entry.customer_email)}">${esc(entry.customer_email)}</a>${entry.customer_phone?` · <a href="tel:${esc(entry.customer_phone)}">${esc(entry.customer_phone)}</a>`:''}</p></div><div class="waitlist-class"><strong>${esc(entry.title)}</strong><span>${esc(entry.location_name)} · ${entry.enrolled}/${entry.capacity} confirmed</span></div><div class="waitlist-actions">${entry.enrolled<entry.capacity?`<button class="btn btn-blue btn-small" data-action="waitlist-promote" data-waitlist-id="${entry.id}">Confirm place</button>`:chip('Class full','changed')}<button class="btn btn-outline dark btn-small" data-action="waitlist-remove" data-waitlist-id="${entry.id}">Remove</button></div></article>`).join('');
    content.innerHTML=shell('Enrolment desk','Run today’s lessons, review capacity and move families from waitlist to confirmed.',`<div class="ops-source"><div><span class="live-dot"></span><strong>${esc(data.source.name)}</strong><small>${esc(data.source.mode)} · refreshed ${dt(data.generated_at)}</small></div><button class="btn btn-soft btn-small" data-route-jump="classes">Class setup</button></div><div class="platform-grid">${metric('Classes today',s.classes_today,'Today’s recurring run sheet','◷')}${metric('Confirmed places',s.confirmed_places,'Across active classes','✓')}${metric('Open places',s.open_places,'Available to enrol','◎')}${metric('Waitlisted',s.waitlisted_swimmers,'Awaiting a place','↗')}<section class="panel panel-pad p-span-12"><div class="panel-head"><div><h2>Today’s run sheet</h2><p>${esc(weekday[new Date().getDay()===0?6:new Date().getDay()-1])} · ordered by lesson start time</p></div>${chip(`${today.length} classes`,today.length?'open':'demo')}</div><div class="run-sheet">${todayRows||empty('No recurring classes are scheduled today.')}</div></section><section class="panel panel-pad p-span-12"><div class="panel-head"><div><h2>Weekly capacity board</h2><p>Schedule, instructor and enrolment pressure at a glance</p></div>${chip(`${s.active_classes} active`,'demo')}</div><div class="schedule-grid">${weekly}</div></section><section class="panel panel-pad p-span-12"><div class="panel-head"><div><h2>Waitlist action queue</h2><p>Confirm only when capacity is available; every action is audited.</p></div>${chip(`${data.waitlist.length} waiting`,data.waitlist.length?'changed':'demo')}</div><div class="waitlist-desk">${queue||empty('No swimmers are waiting for a place.')}</div></section><section class="panel panel-pad p-span-12"><div class="data-boundary" style="margin-top:0"><strong>Enrolment safeguard:</strong> Confirming a place creates the booking, removes the swimmer from the active waitlist, renumbers the queue and notifies the family. Payments and signed enrolment terms remain a production activation workflow.</div></section></div>`);
  }

