  async function adminMerch(content) {
    const data=await api('/api/admin/merch-production');
    const providers=Object.entries(data.providers);
    const ready=data.launch_readiness;
    const routeOptions=[['specialist_uniform','Specialist swim/uniform'],['vistaprint','VistaPrint / bulk'],['printify','Printify POD'],['printify_or_vistaprint','Printify or VistaPrint'],['vistaprint_or_specialist','VistaPrint or specialist'],['manual_review','Manual review']];
    content.innerHTML=shell('Merchandise production','Control samples, supplier costs and launch readiness before anything reaches the live Shopify storefront.',`<div class="platform-grid">${metric('Launch readiness',`${ready.readiness_percent}%`,'Across sample, cost and launch gates','◔')}${metric('Samples approved',`${ready.approved_samples}/${ready.total_products}`,'Physical approval required','✓')}${metric('Costs confirmed',`${ready.costed_products}/${ready.total_products}`,'Needed for reliable margins','$')}${metric('Ready to publish',ready.launchable_products,'Approved sample + launch status','→')}<section class="panel panel-pad p-span-12"><div class="panel-head"><div><h2>Store and supplier pipeline</h2><p>Shopify is the storefront; Printify, VistaPrint and specialist suppliers support the approved production routes.</p></div><a class="btn btn-blue btn-small" href="shop.html" target="_blank">Open public shop</a></div><div class="api-list">${providers.map(([name,provider])=>`<div class="api-row"><div class="api-row-main"><strong>${esc(name.toUpperCase())}</strong><span>${esc(provider.role)}${name==='printify'&&provider.products?.length?` · ${provider.products.length} live products`:''}</span></div><div class="api-row-actions">${chip(provider.configured?'Connected / configured':name==='vistaprint'?'Manual supplier':'Credentials needed',provider.configured?'open':name==='vistaprint'?'changed':'demo')}${provider.url?`<a class="btn btn-soft btn-small" href="${esc(provider.url)}" target="_blank" rel="noopener">Open supplier</a>`:''}</div></div>`).join('')}</div></section><section class="panel panel-pad p-span-12"><div class="panel-head"><div><h2>Product launch controls</h2><p>Retail, cost, margin, sample and supplier decisions are saved in the local management database.</p></div>${chip(`${ready.launchable_products} launchable`,ready.launchable_products?'open':'changed')}</div><div class="table-wrap merch-admin-table"><table class="data-table"><thead><tr><th>Product</th><th>Retail</th><th>Supplier cost</th><th>Projected margin</th><th>Sample</th><th>Launch</th><th>Supplier route</th><th>Personalisation</th><th></th></tr></thead><tbody>${data.catalogue.map(product=>`<tr><td><strong>${esc(product.title)}</strong><br><span class="micro">${esc(product.sku)} · ${esc(product.category)}</span></td><td><input class="table-input" id="product-price-${product.id}" type="number" min="0" step="0.01" value="${(Number(product.price_cents)/100).toFixed(2)}" aria-label="Retail price for ${esc(product.title)}"></td><td><input class="table-input" id="product-cost-${product.id}" type="number" min="0" step="0.01" value="${product.cost_cents==null?'':(Number(product.cost_cents)/100).toFixed(2)}" placeholder="Pending" aria-label="Supplier cost for ${esc(product.title)}"></td><td><strong>${product.margin_percent==null?'—':`${money(product.margin_cents)} · ${product.margin_percent}%`}</strong></td><td><select class="table-input" id="product-sample-${product.id}" aria-label="Sample status for ${esc(product.title)}"><option value="not_ordered" ${product.sample_status==='not_ordered'?'selected':''}>Not ordered</option><option value="ordered" ${product.sample_status==='ordered'?'selected':''}>Ordered</option><option value="received" ${product.sample_status==='received'?'selected':''}>Received</option><option value="changes_required" ${product.sample_status==='changes_required'?'selected':''}>Changes required</option><option value="approved" ${product.sample_status==='approved'?'selected':''}>Approved</option></select></td><td><select class="table-input" id="product-status-${product.id}" aria-label="Launch status for ${esc(product.title)}"><option value="planned" ${product.status==='planned'?'selected':''}>Planned</option><option value="sampling" ${product.status==='sampling'?'selected':''}>Sampling</option><option value="approved" ${product.status==='approved'?'selected':''}>Approved</option><option value="available" ${product.status==='available'?'selected':''}>Available</option><option value="paused" ${product.status==='paused'?'selected':''}>Paused</option></select></td><td><select class="table-input" id="product-route-${product.id}" aria-label="Supplier route for ${esc(product.title)}">${routeOptions.map(([value,label])=>`<option value="${value}" ${product.production.supplier===value?'selected':''}>${label}</option>`).join('')}</select><span class="micro">${esc(product.production.method)}</span></td><td><input class="table-input merch-personalisation-input" id="product-personalisation-${product.id}" value="${esc(product.personalisation||'')}" aria-label="Personalisation plan for ${esc(product.title)}"></td><td><button class="btn btn-soft btn-small" data-action="save-product" data-product-id="${product.id}">Save</button></td></tr>`).join('')}</tbody></table></div></section><section class="panel panel-pad p-span-12"><div class="panel-head"><h2>Launch gates</h2></div><div class="workflow-steps">${data.workflow.map((step,index)=>`<div><span>${index+1}</span><strong>${esc(step)}</strong></div>`).join('')}</div><div class="data-boundary"><strong>Production safeguard:</strong> These controls track decisions but never place supplier orders or publish products automatically. Physical samples, margins and live integration credentials still require business approval.</div></section></div>`);
  }

